    for k in 0..N-1:
        t := 2*pi*k/N
        if |swf(t+pi) + swf(t)| > eps: return NONE   # hypothesis fails
    g(t) := swf(t) - swf(t+pi)
    a, b := 0, pi; ga := g(a)
    repeat until converged:
        m := (a+b)/2; gm := g(m)
        if |gm| <= tol: return (m, swf(m))
        if ga*gm <= 0: b := m else a, ga := m, gm
    return ((a+b)/2, swf((a+b)/2))

