function DETECT_DISCONTINUITY(rule, N, thresh):
    jumps := []
    prev_t := 0; prev_v := rule(0)
    for k in 1..N:
        t := 2*pi*k/N; v := rule(t)
        if |v - prev_v| > thresh:
            append((prev_t + t)/2, |v - prev_v|) to jumps
        prev_t, prev_v := t, v
    return jumps
